var builder = DistributedApplication.CreateBuilder(args);

// One PostgreSQL server for local development; each service gets its own database.
// The data volume keeps job and task state between runs. The password is generated by Aspire
// and kept in the AppHost user secrets, never in git. The image tag matches the PostgreSQL
// version used by the LeiMa.Common test fixtures.
var postgres = builder.AddPostgres("postgres")
    .WithImageTag("17-alpine")
    .WithContainerName("leima-postgres")
    .WithDataVolume();

postgres.AddDatabase("runner");

builder.Build().Run();
